-- Migration: **`plan_templates`**. A reusable plan tree (LT-2). The snapshot is self-contained JSON: once saved, a template does not depend on the plan it was captured from. It carries **no person reference and no identity** (leads, identifiers, codes), and every date is an **offset** from a base date.

CREATE TABLE IF NOT EXISTS "plan_templates" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "name" varchar NOT NULL, "description" text NULL, "snapshot" jsonb NOT NULL, "created_by" varchar NULL, "deleted_at" timestamp with time zone NULL );

CREATE UNIQUE INDEX plan_templates_name ON plan_templates (lower(name)) WHERE deleted_at IS NULL;
